#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    // Check that the whole argument was a valid integer
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // The original program only supports 1 <= n <= 30
    if (n < 1 || n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long cat[31];
    cat[0] = 1ULL;
    for (int i = 1; i <= n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    // The original prints the (n-1)th Catalan number
    printf("%llu\n", cat[n - 1]);
    return 0;
}
